import { Table, ReferenceColumn, BooleanColumn, StringColumn, GenericColumn, OverrideColumn } from '../../db'

export const sys_app = Table({
    actions: ['read', 'update'],
    allowClientScripts: true,
    allowNewFields: true,
    allowUiActions: true,
    allowWebServiceAccess: true,
    attributes: {
        metadata_link_exempt: true,
        synch_attachments: true,
        update_synch: true,
    },
    audit: true,
    extends: 'sys_scope',
    label: 'Custom Application',
    name: 'sys_app',
    schema: {
        menu: ReferenceColumn({
            label: [
                {
                    hint: "This application's primary menu where default table modules will reside",
                    label: 'Menu',
                    plural: 'Menus',
                },
            ],
            referenceTable: 'sys_app_application',
            dynamicCreation: true,
            dynamicCreationScript:
                "current.sys_scope = parent.sys_id; current.title = value; current.active = parent.active; current.name = SncAppsUI.generateNameFromLabel(value); current.category = 'e0355b31ef303000a61d5a3615c0fb78';  current.insert();",
        }),
        uninstall_blocked: BooleanColumn({
            default: false,
            label: 'Uninstall Blocked',
        }),
        license_definition: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: [
                {
                    hint: 'License definition for the current version of the application',
                    label: 'License Definition',
                    plural: 'License Definitions',
                },
            ],
            referenceTable: 'sys_app_license_defn',
            referenceQual: "javascript:'sys_scope.scope=' + current.scope",
            dynamicCreation: true,
            dynamicCreationScript:
                'current.sys_scope = parent.sys_id; current.active = parent.active; current.insert();',
        }),
        store_url: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
            },
            label: [
                {
                    hint: 'Identifies the application URL for configuring the offering in the app store',
                    label: 'Store URL',
                    plural: 'Store URLs',
                },
            ],
        }),
        sys_id: GenericColumn({
            mandatory: false,
            label: 'Sys ID',
            read_only: false,
            active: true,
            column_type: 'GUID',
        }),
        installed_as_dependency: BooleanColumn({
            default: false,
            label: 'Installed via Dependency',
        }),
        store_correlation_id: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
            },
            label: [
                {
                    hint: 'Identifies the unique application id assigned by the app store',
                    label: 'Store correlation ID',
                    plural: 'Store correlation IDs',
                },
            ],
        }),
        user_role: ReferenceColumn({
            label: [
                {
                    hint: 'Role required for end users to access this application and its tables',
                    label: 'User role',
                    plural: 'User roles',
                },
            ],
            referenceTable: 'sys_user_role',
            dynamicCreation: true,
            dynamicCreationScript:
                "current.sys_scope = parent.sys_id; current.name = value; var s = parent.scope.toString(); if(!parent.scope.nil() && parent.scope.toString() != 'global' && value.indexOf(parent.scope.toString() + '.') == 0) { current.suffix = value.substring(parent.scope.toString().length + 1, value.length); } current.insert();",
        }),
        sys_code: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
            },
            label: [
                {
                    hint: 'Internal code used to identify plugins',
                    label: 'Code',
                    plural: 'Codes',
                },
            ],
            maxLength: 100,
        }),
        hide_on_ui: BooleanColumn({
            default: false,
            label: 'Hidden on ui',
        }),
        licensable: OverrideColumn({
            baseTable: 'sys_package',
            default: 'true',
        }),
        version: OverrideColumn({
            baseTable: 'sys_package',
            default: '1.0.0',
        }),
    },
    textIndex: true,
})
